import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser } from '../services/api';
import { getFranchises } from '../services/api';

const CreateUser = ({ loggedInUser }) => {  // Passing the logged-in user as a prop
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: [],
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]); 
  const [editingUser, setEditingUser] = useState(null); 

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchUsers = async () => {
      try {
        const response = await getUsers();
        setUsers(response);
      } catch (error) {
        alert('Error fetching users: ' + (error.response?.data?.message || error.message));
      }
    };

    fetchFranchises();
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === "franchiseId") {
      // Handle multiple franchise selection
      const selectedFranchises = Array.from(e.target.selectedOptions, option => option.value);
      setFormData({ ...formData, [name]: selectedFranchises });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (editingUser) {
        await updateUser(editingUser._id, formData);
        alert('User updated successfully!');
      } else {
        await createUser(formData);
        alert('User created successfully!');
      }

      setEditingUser(null);
      setFormData({ username: '', password: '', name: '', role: 'user', franchiseId: [] });

      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Error creating/updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      username: user.username,
      password: '', 
      name: user.name,
      role: user.role,
      franchiseId: user.franchiseId || [],
    });
  };

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      alert('User deleted successfully!');
      const response = await getUsers();
      setUsers(response); 
    } catch (error) {
      console.error("Failed to delete user:", error.message);
      alert('Failed to delete user. Please try again.');
    }
  };

  return (
    <div className="create-user-container">
      <h1>{editingUser ? 'Edit User' : 'Create User'}</h1>
      <form onSubmit={handleSubmit} className="form-container">
        <div className="form-group">
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            name="username"
            placeholder="Username"
            value={formData.username}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required={!editingUser}
          />
        </div>
        <div className="form-group">
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="role">Role:</label>
          <select
            id="role"
            name="role"
            value={formData.role}
            onChange={handleChange}
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
            <option value="superadmin">Super Admin</option>
          </select>
        </div>
        <div className="form-group">
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            multiple
            required
          >
            <option value="">Select Franchises</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} - {franchise.location}
              </option>
            ))}
          </select>
        </div>
        <button type="submit" className="submit-btn">{editingUser ? 'Update User' : 'Create User'}</button>
      </form>

      <h2>All Users</h2>
      <table className="user-table">
        <thead>
          <tr>
            <th>Username</th>
            <th>Name</th>
            <th>Role</th>
            <th>Franchise</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => {
            const franchiseNames = user.franchiseId?.map((id) => {
              const franchise = franchises.find(f => f._id === id);
              return franchise ? franchise.name : 'N/A';
            }).join(', ') || 'N/A';
            
            return (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>{franchiseNames}</td>
                <td>
                  {loggedInUser.role !== 'superadmin' && (
                    <button onClick={() => handleEdit(user)} className="edit-btn">Edit</button>
                  )}
                  {loggedInUser.role !== 'admin' && (
                    <button onClick={() => handleDelete(user._id)} className="delete-btn">Delete</button>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <style>
        {`
          /* General Styles */
          .create-user-container {
            font-family: Arial, sans-serif;
            max-width: 900px;
            margin: 20px auto;
            padding: 20px;
            background-color: #f9f9f9;
            border-radius: 10px;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
          }

          h1, h2 {
            color: #333;
            text-align: center;
          }

          /* Form Styles */
          .form-container {
            display: grid;
            gap: 20px;
            margin-bottom: 30px;
          }

          .form-group {
            display: flex;
            flex-direction: column;
          }

          label {
            font-weight: bold;
            margin-bottom: 5px;
          }

          input, select {
            padding: 10px;
            border-radius: 5px;
            border: 1px solid #ccc;
            font-size: 16px;
          }

          input:focus, select:focus {
            border-color: #007bff;
            outline: none;
          }

          /* Buttons */
          .submit-btn {
            padding: 10px 20px;
            border: none;
            background-color: #007bff;
            color: white;
            font-size: 16px;
            border-radius: 5px;
            cursor: pointer;
            transition: background-color 0.3s;
          }

          .submit-btn:hover {
            background-color: #0056b3;
          }

          /* Table Styles */
          .user-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 20px;
          }

          .user-table th, .user-table td {
            padding: 12px;
            text-align: left;
            border-bottom: 1px solid #ddd;
          }

          .user-table th {
            background-color: #f1f1f1;
          }

          .user-table tr:nth-child(even) {
            background-color: #f9f9f9;
          }

          .edit-btn, .delete-btn {
            padding: 5px 10px;
            margin: 5px;
            border-radius: 5px;
            border: none;
            cursor: pointer;
          }

          .edit-btn {
            background-color: #28a745;
            color: white;
